#include <stdio.h>
int main(void) {
    int a[] = {5, 2, 8, 1, 9};
    int n = (int)(sizeof a / sizeof a[0]);
    int sum = 0, lo = a[0], hi = a[0];
    for (int i = 0; i < n; i++) {
        sum += a[i];
        if (a[i] < lo) lo = a[i];
        if (a[i] > hi) hi = a[i];
    }
    printf("sum=%d min=%d max=%d\n", sum, lo, hi);
    return 0;
}

#include <stdio.h>
int main(void) {
    int m[2][3] = {{1,2,3},{4,5,6}};
    int t[3][2];
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 3; j++) t[j][i] = m[i][j];
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 2; j++) printf("%d ", t[i][j]);
        printf("\n");
    }
    return 0;
}
